import numpy as np

def cashflows(perf, terms):
    n_paths, n_dates, n_assets = perf.shape
    cash = np.zeros((n_paths, n_dates), dtype=float)
    notional = float(terms.get("notional", 1000.0))
    final_index = int(terms.get("final_index", n_dates - 1))
    autocall = terms.get("autocall")
    coupon = terms.get("coupon")
    downside = terms.get("downside")

    active = np.ones(n_paths, dtype=bool)
    unpaid = np.zeros(n_paths, dtype=float)

    for k in range(n_dates):
        if not np.any(active):
            break
        is_call = False
        called = np.zeros(n_paths, dtype=bool)
        if autocall is not None:
            call_amounts = autocall.get("call_amounts")
            trigger = autocall.get("trigger")
            if call_amounts is not None and k < len(call_amounts) and call_amounts[k] is not None:
                is_call = True
                if n_assets == 1:
                    pk = perf[:, k, 0]
                else:
                    pk = np.min(perf[:, k, :], axis=1)
                called = active & (pk >= trigger)
                if np.any(called):
                    cash[called, k] += float(call_amounts[k])
        if coupon is not None:
            amounts = coupon.get("amounts")
            barrier = coupon.get("barrier")
            memory = coupon.get("memory", False)
            if amounts is not None and k < len(amounts) and amounts[k] is not None:
                if n_assets == 1:
                    ck = perf[:, k, 0]
                else:
                    ck = np.min(perf[:, k, :], axis=1)
                eligible = active & (ck >= barrier)
                if memory:
                    not_elig = active & (~eligible)
                    unpaid[not_elig] += float(amounts[k])
                    if np.any(eligible):
                        cash[eligible, k] += float(amounts[k]) + unpaid[eligible]
                        unpaid[eligible] = 0.0
                else:
                    if np.any(eligible):
                        cash[eligible, k] += float(amounts[k])
        if is_call and np.any(called):
            active[called] = False

    if np.any(active):
        if n_assets == 1:
            final_perf = perf[active, final_index, 0]
        else:
            final_perf = np.min(perf[active, final_index, :], axis=1)

        unsupported = terms.get("unsupported_features", [])
        has_digital = False
        for s in unsupported:
            if "Digital" in s:
                has_digital = True
                break

        if has_digital:
            digital = 0.0904
            level = float(downside["level"]) if downside is not None and "level" in downside else 0.9
            gearing = float(downside["gearing"]) if downside is not None and "gearing" in downside else 1.11111
            above = final_perf >= level
            pay_up = notional * (1.0 + digital)
            pay_down = notional + notional * (final_perf - level) * gearing
            pay_down = np.maximum(pay_down, 0.0)
            pay = np.where(above, pay_up, pay_down)
        else:
            if downside is not None and downside.get("kind") == "buffer":
                level = float(downside.get("level", 0.0))
                gearing = float(downside.get("gearing", 1.0))
                upside = terms.get("upside")
                if upside is not None:
                    lev = float(upside.get("leverage", 1.0))
                    cap = upside.get("cap")
                    excess = np.maximum(final_perf - 1.0, 0.0)
                    ret = excess * lev
                    if cap is not None:
                        ret = np.minimum(ret, float(cap))
                    pay_up = notional * (1.0 + ret)
                    pay_up = np.where(final_perf < 1.0, notional, pay_up)
                else:
                    pay_up = np.full_like(final_perf, notional, dtype=float)
                pay_down = notional + notional * (final_perf - level) * gearing
                pay_down = np.maximum(pay_down, 0.0)
                pay = np.where(final_perf >= level, pay_up, pay_down)
            elif downside is not None and downside.get("kind") == "barrier":
                level = float(downside.get("level", 0.0))
                gearing = float(downside.get("gearing", 1.0))
                pay = np.where(final_perf >= level, notional, np.maximum(notional * final_perf * gearing, 0.0))
            else:
                pay = np.full_like(final_perf, notional, dtype=float)
        cash[active, final_index] += pay

    return cash
